arguments.command:
bundle exec ruby -e '
require "stackprof"
data = Marshal.load(File.binread("tmp/test_prof/requests-baseline-wall.dump"))
total = data[:samples].to_f
frames = data[:frames].values

def show_matching(frames, total, title, limit = 30, &pred)
  puts "\n=== #{title} ==="
  frames.select(&pred).sort_by { |f| -f[:total_samples] }.first(limit).each do |f|
    pct = (f[:total_samples] / total * 100).round(2)
    spct = (f[:samples] / total * 100).round(2)
    printf "%6.2f%% (%5.2f%% self) %7d  %s  [%s:%s]\n", pct, spct, f[:total_samples], f[:name], f[:file].to_s.sub(/.*\/gems\//, "gems/").sub(Dir.pwd + "/", ""), f[:line]
  end
end

show_matching(frames, total, "Routing / reload_routes", 25) { |f| f[:file].to_s =~ /routing|routes/ || f[:name] =~ /route/i }
show_matching(frames, total, "Sidekiq workers (app/workers)", 25) { |f| f[:file].to_s.include?("/app/workers/") || f[:name] =~ /Sidekiq/ }
show_matching(frames, total, "Top spec/requests frames", 30) { |f| f[:file].to_s.include?("spec/requests/") }
show_matching(frames, total, "Top app/controllers & app/views & app/serializers", 30) { |f| f[:file].to_s =~ /app\/(controllers|views|serializers)/ }
show_matching(frames, total, "Top spec/support & spec/rails_helper", 20) { |f| f[:file].to_s =~ /spec\/(support|rails_helper|spec_helper)/ }
'

